insert into public.instrument_version (version_id, semver, status) values ('ins_v1_1', '1.1', 'DRAFT');
insert into public.rules_version (version_id, semver, status, published_at) values ('rul_v2_0', '2.0', 'PUBLISHED', now());
insert into public.scenario (version_id, scenario_id, dimension, sequence, title, prompt_now, prompt_preferred) values
  ('ins_v1_1', 'D1-S1', 'D1', 1, $q$Organisational Character$q$, $q$How would you describe the fundamental character of this organisation today?$q$, $q$PREFERRED perspective: What fundamental character must this organisation have five years from now?$q$),
  ('ins_v1_1', 'D1-S2', 'D1', 2, $q$New Employee Experience$q$, $q$What do new employees consistently notice and remark upon within their first few weeks?$q$, $q$PREFERRED perspective: What should new employees notice and remark upon within their first few weeks in the future organisation?$q$),
  ('ins_v1_1', 'D1-S3', 'D1', 3, $q$Response to Adversity$q$, $q$How does this organisation characteristically respond when things go significantly wrong?$q$, $q$PREFERRED perspective: How should this organisation respond when things go significantly wrong in the future?$q$),
  ('ins_v1_1', 'D2-S1', 'D2', 1, $q$Primary Leadership Orientation$q$, $q$How would you best describe the dominant approach that leaders take in this organisation?$q$, $q$PREFERRED perspective: What dominant approach should leaders take in this organisation five years from now?$q$),
  ('ins_v1_1', 'D2-S2', 'D2', 2, $q$How Leaders Invest Their Time$q$, $q$How do leaders in this organisation characteristically spend their discretionary time and focused attention?$q$, $q$PREFERRED perspective: How should leaders spend their discretionary time and focused attention in the future organisation?$q$),
  ('ins_v1_1', 'D2-S3', 'D2', 3, $q$What Leaders Are Recognised For$q$, $q$What kinds of leadership contributions are most valued, celebrated, and emulated in this organisation?$q$, $q$PREFERRED perspective: What kinds of leadership contributions should be most valued, celebrated, and emulated in the future?$q$),
  ('ins_v1_1', 'D3-S1', 'D3', 1, $q$Core Management Philosophy$q$, $q$How would you characterise the dominant philosophy used to manage and direct people in this organisation?$q$, $q$PREFERRED perspective: What philosophy should dominate how people are managed and directed five years from now?$q$),
  ('ins_v1_1', 'D3-S2', 'D3', 2, $q$Development and Growth Approach$q$, $q$How does this organisation primarily develop, grow, and invest in the capabilities of its people?$q$, $q$PREFERRED perspective: How should this organisation develop, grow, and invest in the capabilities of its people in the future?$q$),
  ('ins_v1_1', 'D3-S3', 'D3', 3, $q$Performance Conversation Style$q$, $q$How are performance conversations and feedback primarily conducted within this organisation?$q$, $q$PREFERRED perspective: How should performance conversations and feedback be conducted in the future organisation?$q$),
  ('ins_v1_1', 'D4-S1', 'D4', 1, $q$Primary Bonding Mechanism$q$, $q$What most fundamentally holds this organisation together and creates a coherent collective identity?$q$, $q$PREFERRED perspective: What should most fundamentally hold this organisation together and create a coherent collective identity in the future?$q$),
  ('ins_v1_1', 'D4-S2', 'D4', 2, $q$What Makes People Stay$q$, $q$What is the primary reason that people decide to remain in this organisation over the long term?$q$, $q$PREFERRED perspective: What should be the primary reason people decide to remain in this organisation over the long term?$q$),
  ('ins_v1_1', 'D4-S3', 'D4', 3, $q$Identity Through Change$q$, $q$How does this organisation maintain a coherent sense of identity when going through significant change?$q$, $q$PREFERRED perspective: How should this organisation maintain a coherent sense of identity through significant change in the future?$q$),
  ('ins_v1_1', 'D5-S1', 'D5', 1, $q$Primary Strategic Orientation$q$, $q$What is the most prominent orientation guiding how this organisation approaches strategy?$q$, $q$PREFERRED perspective: What orientation should be most prominent in how this organisation approaches strategy five years from now?$q$),
  ('ins_v1_1', 'D5-S2', 'D5', 2, $q$Budget and Resource Allocation Logic$q$, $q$When resources are allocated in this organisation, what consistently and reliably receives strategic priority?$q$, $q$PREFERRED perspective: When resources are allocated in the future, what should consistently and reliably receive strategic priority?$q$),
  ('ins_v1_1', 'D5-S3', 'D5', 3, $q$Long-Term Investment Philosophy$q$, $q$What investment logic most characteristically reflects how this organisation thinks about the next five years?$q$, $q$PREFERRED perspective: What investment logic should characterise how this organisation thinks about the next five years?$q$),
  ('ins_v1_1', 'D6-S1', 'D6', 1, $q$Organisational Success Definition$q$, $q$How does this organisation primarily define and articulate what success means for it?$q$, $q$PREFERRED perspective: How should this organisation define and articulate what success means for it in the future?$q$),
  ('ins_v1_1', 'D6-S2', 'D6', 2, $q$What Gets Celebrated$q$, $q$What types of achievements and behaviours are most enthusiastically recognised and celebrated here?$q$, $q$PREFERRED perspective: What types of achievements and behaviours should be most enthusiastically recognised and celebrated in the future?$q$),
  ('ins_v1_1', 'D6-S3', 'D6', 3, $q$Performance Measurement Philosophy$q$, $q$What types of metrics and measures most fundamentally reflect how this organisation tracks its performance?$q$, $q$PREFERRED perspective: What types of metrics and measures should most fundamentally reflect how this organisation tracks performance five years from now?$q$);
insert into public.scenario_statement (version_id, scenario_id, orientation, text) values
  ('ins_v1_1', 'D1-S1', 'ENGAGE', $q$This organisation is fundamentally a people-centred community. Deep relationships, mutual care, and shared purpose define daily experience. People invest in one another as whole human beings, not merely as role-holders or performance units.$q$),
  ('ins_v1_1', 'D1-S1', 'INNOVATE', $q$This organisation is fundamentally an ideas engine. Bold experimentation, creative disruption, and the freedom to challenge convention define who we are. We move fast and prize originality over conformity at every level.$q$),
  ('ins_v1_1', 'D1-S1', 'PERFORM', $q$This organisation is fundamentally a performance machine. Ambitious goals, relentless execution, and measurable outcomes define us. We compete hard, celebrate achievement loudly, and hold ourselves to exacting standards.$q$),
  ('ins_v1_1', 'D1-S1', 'GOVERN', $q$This organisation is fundamentally a system of order. Clear structures, defined processes, and consistent standards define how we work. We value precision, reliability, and systematic discipline above improvisation.$q$),
  ('ins_v1_1', 'D1-S2', 'ENGAGE', $q$New employees immediately notice the warmth and genuine inclusion. Colleagues go out of their way to welcome them, offer proactive support, and make them feel part of something that transcends any single role or task.$q$),
  ('ins_v1_1', 'D1-S2', 'INNOVATE', $q$New employees immediately notice the energy and creative freedom. They are quickly encouraged to question existing approaches, propose ideas boldly, and take ownership of challenges without waiting for permission.$q$),
  ('ins_v1_1', 'D1-S2', 'PERFORM', $q$New employees immediately notice the pace and the performance expectations. They quickly understand that results matter, targets are taken seriously, and strong delivery is expected and closely observed from the very first week.$q$),
  ('ins_v1_1', 'D1-S2', 'GOVERN', $q$New employees immediately notice the structure and operational clarity. There are established ways of doing things, clear reporting lines, and thoroughly documented expectations for every level and function across the organisation.$q$),
  ('ins_v1_1', 'D1-S3', 'ENGAGE', $q$When things go seriously wrong, we rally together as a community. People offer genuine support, share the burden collectively, and focus on protecting team morale while communicating openly and looking after each other through difficulty.$q$),
  ('ins_v1_1', 'D1-S3', 'INNOVATE', $q$When things go seriously wrong, we treat it as essential learning. We diagnose rapidly, experiment with recovery approaches, and view failure as data that makes us smarter, not as a signal to blame, retreat, or become more risk-averse.$q$),
  ('ins_v1_1', 'D1-S3', 'PERFORM', $q$When things go seriously wrong, we focus intensely on getting back on track. We define the performance gap, set clear recovery targets, and expect everyone to work urgently and accountably until performance standards are restored.$q$),
  ('ins_v1_1', 'D1-S3', 'GOVERN', $q$When things go seriously wrong, we follow the established protocol. We activate risk management procedures, document accurately what occurred, and ensure that proper escalation and accountability channels are adhered to without exception.$q$),
  ('ins_v1_1', 'D2-S1', 'ENGAGE', $q$Leaders are primarily coaches and mentors. They prioritise development conversations, team cohesion, and creating environments where people feel genuinely seen, valued, and supported in their professional and personal growth.$q$),
  ('ins_v1_1', 'D2-S1', 'INNOVATE', $q$Leaders are primarily visionaries and champions of change. They set ambitious directions, encourage unconventional thinking, and give people genuine autonomy to experiment and find solutions that have never been tried before.$q$),
  ('ins_v1_1', 'D2-S1', 'PERFORM', $q$Leaders are primarily drivers and scorekeepers. They establish challenging targets, track performance rigorously, and hold people firmly to clear standards of measurable output, delivery, and commercial contribution.$q$),
  ('ins_v1_1', 'D2-S1', 'GOVERN', $q$Leaders are primarily architects and stewards of process. They design efficient operating systems, maintain quality and consistency across operations, and preserve clear accountability structures throughout the organisation.$q$),
  ('ins_v1_1', 'D2-S2', 'ENGAGE', $q$Leaders invest significant time in coaching conversations, structured listening sessions, team cohesion activities, and ensuring that the human dimensions of work are not neglected or subordinated to performance pressure alone.$q$),
  ('ins_v1_1', 'D2-S2', 'INNOVATE', $q$Leaders invest significant time scanning emerging trends, incubating new initiatives, removing barriers to experimentation, and personally sponsoring projects that challenge existing assumptions and inherited approaches.$q$),
  ('ins_v1_1', 'D2-S2', 'PERFORM', $q$Leaders invest significant time reviewing performance data, calibrating against targets, eliminating execution bottlenecks, and actively pushing for consistently higher performance standards and outcomes across all functions.$q$),
  ('ins_v1_1', 'D2-S2', 'GOVERN', $q$Leaders invest significant time in systems improvement, process design, compliance management, and ensuring that operational quality and established standards are consistently upheld and improved across all areas.$q$),
  ('ins_v1_1', 'D2-S3', 'ENGAGE', $q$Leaders are most celebrated for developing others, building deeply motivated and cohesive teams, handling difficult human situations with genuine wisdom and care, and creating authentic belonging within their areas of responsibility.$q$),
  ('ins_v1_1', 'D2-S3', 'INNOVATE', $q$Leaders are most celebrated for inspiring new thinking, launching bold initiatives ahead of market demands, championing change before it is explicitly required, and consistently unlocking the creative potential of the people around them.$q$),
  ('ins_v1_1', 'D2-S3', 'PERFORM', $q$Leaders are most celebrated for delivering outstanding results, consistently exceeding targets, building elite-performing teams, and generating measurable commercial or operational wins that materially advance the organisation's position.$q$),
  ('ins_v1_1', 'D2-S3', 'GOVERN', $q$Leaders are most celebrated for building reliable and efficient systems, preventing costly problems before they arise, and maintaining consistent quality and compliance standards rigorously across their areas of responsibility.$q$),
  ('ins_v1_1', 'D3-S1', 'ENGAGE', $q$Employees are managed through relationship and meaningful participation. Managers prioritise collaborative decision-making, seek genuine team consensus, and ensure that all members have voice in matters that directly affect their daily work.$q$),
  ('ins_v1_1', 'D3-S1', 'INNOVATE', $q$Employees are managed through autonomy and creative challenge. Managers provide generous space for independent thinking, tolerate productive failure as a natural element of learning, and actively reward intellectual initiative and experimentation.$q$),
  ('ins_v1_1', 'D3-S1', 'PERFORM', $q$Employees are managed through clear targets and firm accountability. Managers set demanding performance expectations, track progress against measurable goals rigorously, and hold people to consistently high standards of delivery.$q$),
  ('ins_v1_1', 'D3-S1', 'GOVERN', $q$Employees are managed through defined roles and established procedures. Managers ensure people understand their responsibilities clearly, adhere to documented protocols consistently, and perform within their designated remit reliably.$q$),
  ('ins_v1_1', 'D3-S2', 'ENGAGE', $q$Development is relationship-led. The most valued growth experiences are mentoring relationships, peer learning circles, team-based stretch projects, and the opportunity to develop alongside trusted, respected, and more experienced colleagues.$q$),
  ('ins_v1_1', 'D3-S2', 'INNOVATE', $q$Development is discovery-led. The most valued experiences include stretch assignments beyond comfort zones, cross-functional exposure, experimentation with new approaches, and regular access to cutting-edge external thinking and innovation.$q$),
  ('ins_v1_1', 'D3-S2', 'PERFORM', $q$Development is results-led. The most valued experiences are high-stakes projects with real accountability, performance coaching under meaningful pressure, visible delivery moments, and fast-track advancement for consistently strong performers.$q$),
  ('ins_v1_1', 'D3-S2', 'GOVERN', $q$Development is competency-led. The most valued experiences are structured technical training programmes, professional certification, methodical skill-building against defined competency frameworks, and clear progression milestones with specified criteria.$q$),
  ('ins_v1_1', 'D3-S3', 'ENGAGE', $q$Performance conversations are primarily supportive and developmental in tone. Feedback is delivered within a context of genuine care for the person, and performance challenges are met with coaching support and encouragement rather than pressure or sanction.$q$),
  ('ins_v1_1', 'D3-S3', 'INNOVATE', $q$Performance conversations are primarily exploratory and future-oriented. The primary focus is on learning from experience, adapting approaches, and identifying the next bold challenge to pursue, rather than dwelling at length on past shortfalls.$q$),
  ('ins_v1_1', 'D3-S3', 'PERFORM', $q$Performance conversations are primarily candid and accountability-driven. Honest feedback is delivered directly and without excessive softening, underperformance is named clearly, and improvement expectations are specific, measurable, and time-bound.$q$),
  ('ins_v1_1', 'D3-S3', 'GOVERN', $q$Performance conversations are primarily structured and standards-based. Reviews follow a consistent and documented format, are benchmarked against defined competency frameworks, and result in recorded development plans with measurable milestones.$q$),
  ('ins_v1_1', 'D4-S1', 'ENGAGE', $q$What holds this organisation together is the quality of our relationships. Loyalty, mutual respect, and genuine care for each other create bonds that survive difficult periods, leadership transitions, and sustained external pressure.$q$),
  ('ins_v1_1', 'D4-S1', 'INNOVATE', $q$What holds this organisation together is our shared hunger for what is possible. A collective excitement about the new, the untried, and the transformative creates enduring unity and common purpose across all functions and hierarchical levels.$q$),
  ('ins_v1_1', 'D4-S1', 'PERFORM', $q$What holds this organisation together is our shared competitive drive. A collective commitment to winning, outperforming others, and delivering ambitious results creates a unifying force and common identity across all divisions.$q$),
  ('ins_v1_1', 'D4-S1', 'GOVERN', $q$What holds this organisation together is adherence to shared systems and standards. Common processes, clearly defined policies, and consistent expectations create a unifying operational framework that guides and aligns collective behaviour.$q$),
  ('ins_v1_1', 'D4-S2', 'ENGAGE', $q$People remain primarily because of the depth of relationships and genuine sense of belonging they experience here. The quality of their human connections (with colleagues, managers, and teams) is the decisive factor in their decision to stay.$q$),
  ('ins_v1_1', 'D4-S2', 'INNOVATE', $q$People remain primarily because of the intellectual stimulation and growth the organisation continuously provides. The opportunity to work on genuinely novel problems, learn continuously, and pioneer meaningful solutions is the decisive retention factor.$q$),
  ('ins_v1_1', 'D4-S2', 'PERFORM', $q$People remain primarily because of the high-performance culture and the compelling career trajectory it enables. The chance to achieve at a high level, advance rapidly, and be recognised for exceptional contribution keeps strong performers committed over time.$q$),
  ('ins_v1_1', 'D4-S2', 'GOVERN', $q$People remain primarily because of the stability, security, and predictability the organisation dependably provides. Clear expectations, reliable processes, and predictable career progression create a sense of institutional safety that sustains long-term loyalty.$q$),
  ('ins_v1_1', 'D4-S3', 'ENGAGE', $q$During significant change, the organisation anchors to its people-first values. Preserving trust, ensuring that no one is left behind, and maintaining relational continuity are the non-negotiable constants through any period of disruption or transformation.$q$),
  ('ins_v1_1', 'D4-S3', 'INNOVATE', $q$During significant change, the organisation maintains identity through its appetite for reinvention. Change is not experienced as a threat but as a natural expression of who we are; agility and continuous adaptation are our defining cultural constants.$q$),
  ('ins_v1_1', 'D4-S3', 'PERFORM', $q$During significant change, the organisation maintains identity through its performance orientation. The goal-driven culture and competitive spirit remain consistent and recognisable regardless of what is structurally changing around and beneath them.$q$),
  ('ins_v1_1', 'D4-S3', 'GOVERN', $q$During significant change, the organisation maintains identity through structural discipline. Established processes provide institutional continuity, and well-documented protocols ensure operational consistency and predictability despite external disruption.$q$),
  ('ins_v1_1', 'D5-S1', 'ENGAGE', $q$Our strategy is oriented primarily toward human capital excellence. We believe that investing deeply in people (their skills, wellbeing, engagement, and development) is the most reliable and sustainable route to long-term organisational performance.$q$),
  ('ins_v1_1', 'D5-S1', 'INNOVATE', $q$Our strategy is oriented primarily toward future opportunity and emerging capability. We invest ahead of where the market is moving, acquire leading capabilities early, and consistently prioritise positioning for what comes next over optimising what already exists.$q$),
  ('ins_v1_1', 'D5-S1', 'PERFORM', $q$Our strategy is oriented primarily toward market leadership and sustained commercial excellence. We invest in capabilities that strengthen our competitive position, grow our revenue base, and deliver consistently superior returns to stakeholders.$q$),
  ('ins_v1_1', 'D5-S1', 'GOVERN', $q$Our strategy is oriented primarily toward operational excellence and scalable efficiency. We invest in process improvement, quality management systems, enterprise risk reduction, and the infrastructure required to grow without compromising standards.$q$),
  ('ins_v1_1', 'D5-S2', 'ENGAGE', $q$People programmes receive consistent strategic priority. Learning and development budgets, employee experience investments, wellbeing programmes, and engagement initiatives are treated as core strategic expenditures, not discretionary or deferrable costs.$q$),
  ('ins_v1_1', 'D5-S2', 'INNOVATE', $q$Innovation and growth programmes receive consistent strategic priority. Research and development, new capability investment, technology pilots, and market exploration are protected, including during periods of financial constraint and competitive pressure.$q$),
  ('ins_v1_1', 'D5-S2', 'PERFORM', $q$Revenue-generating and commercial activities receive consistent strategic priority. Sales capability, marketing investment, customer acquisition, and performance management infrastructure are the primary beneficiaries of resource decisions.$q$),
  ('ins_v1_1', 'D5-S2', 'GOVERN', $q$Systems infrastructure and compliance receive consistent strategic priority. Technology investment, process re-engineering, audit readiness, quality management, and institutional risk infrastructure are treated as non-negotiable operational foundations.$q$),
  ('ins_v1_1', 'D5-S3', 'ENGAGE', $q$Over a five-year horizon, we prioritise culture-building, employer brand strength, and talent pipeline development. We believe that an organisation with genuinely outstanding people practices will consistently outperform across any market or economic condition.$q$),
  ('ins_v1_1', 'D5-S3', 'INNOVATE', $q$Over a five-year horizon, we prioritise positioning at the frontier of our industry. Early investments in emerging technology, unconventional business models, and frontier approaches are how we intend to create and sustain durable competitive leadership.$q$),
  ('ins_v1_1', 'D5-S3', 'PERFORM', $q$Over a five-year horizon, we prioritise sustained commercial outperformance and market expansion. We set progressively demanding performance targets and build the execution capabilities required to consistently deliver against them at scale.$q$),
  ('ins_v1_1', 'D5-S3', 'GOVERN', $q$Over a five-year horizon, we prioritise building reliable, scalable operating systems and institutional resilience. We invest in the infrastructure, standards, and process discipline required to deliver consistent excellence as the organisation scales.$q$),
  ('ins_v1_1', 'D6-S1', 'ENGAGE', $q$Success means that our people genuinely thrive. A highly engaged workforce, low voluntary turnover, outstanding employee experience scores, and leaders who invest consistently in developing others are the defining measures of our success as an organisation.$q$),
  ('ins_v1_1', 'D6-S1', 'INNOVATE', $q$Success means that we lead our industry in originality and adaptive capability. Being consistently first with genuinely novel solutions, achieving recognition as pioneers and thought leaders, and building an innovation reputation that attracts exceptional talent define our success.$q$),
  ('ins_v1_1', 'D6-S1', 'PERFORM', $q$Success means that we win commercially and outpace competition. Revenue growth, market share gains, consistent outperformance of competitors, and delivering superior returns to our stakeholders are the primary definitions of what success means here.$q$),
  ('ins_v1_1', 'D6-S1', 'GOVERN', $q$Success means that we operate with systemic excellence. Consistent quality at scale, zero material compliance failures, efficient and reliable process execution, and dependable delivery within agreed cost and timeline parameters define success for us.$q$),
  ('ins_v1_1', 'D6-S2', 'ENGAGE', $q$Genuine teamwork, remarkable acts of care, and outstanding cross-functional collaboration are celebrated most enthusiastically. Recognition focuses equally on collective achievement and individual contribution, and stories of human connection carry significant cultural status.$q$),
  ('ins_v1_1', 'D6-S2', 'INNOVATE', $q$Breakthrough thinking, bold experiments, and the intellectual courage to attempt something genuinely new are celebrated most enthusiastically, regardless of whether every experiment ultimately succeeds or falls short of initial ambitions.$q$),
  ('ins_v1_1', 'D6-S2', 'PERFORM', $q$Exceptional commercial results, ambitious targets exceeded, and elite individual and team performance are celebrated most enthusiastically. Numbers, competitive rankings, and tangible organisational wins carry enduring and significant cultural status.$q$),
  ('ins_v1_1', 'D6-S2', 'GOVERN', $q$Flawless execution, consistently excellent quality, clean audit and compliance outcomes, and the sustained discipline to maintain high standards under operational pressure are what this organisation celebrates most enthusiastically and publicly.$q$),
  ('ins_v1_1', 'D6-S3', 'ENGAGE', $q$We track success by the health and vitality of our people and their working relationships. Employee engagement scores, voluntary retention rates, team health indices, developmental feedback quality, and wellbeing indicators are the measures that carry the most weight here.$q$),
  ('ins_v1_1', 'D6-S3', 'INNOVATE', $q$We track success by the vibrancy of our innovation pipeline and our rate of institutional learning. Speed of new initiative generation, successful pilot conversions, adoption velocity of new approaches, and experimentation frequency are the metrics we prioritise.$q$),
  ('ins_v1_1', 'D6-S3', 'PERFORM', $q$We track success through rigorous commercial and operational KPIs. Revenue targets, margin ratios, market share data, customer acquisition metrics, and competitive positioning indicators are the primary performance measures we report upon and act on.$q$),
  ('ins_v1_1', 'D6-S3', 'GOVERN', $q$We track success through quality, compliance, and operational efficiency metrics. Error rates, compliance scores, service-level adherence rates, process efficiency ratios, and audit outcomes are the foundational measures of our effectiveness as an organisation.$q$);
insert into public.item (version_id, item_id, block, dimension, sequence, scale_type, title, canonical_text) values
  ('ins_v1_1', 'D7-01', 'LIKERT', 'D7', 1, '1-5', null, $q$Our organisation actively encourages adoption of new digital tools and technologies to improve how work is designed and executed.$q$),
  ('ins_v1_1', 'D7-02', 'LIKERT', 'D7', 2, '1-5', null, $q$When new technology is introduced, most employees approach it with genuine curiosity and openness rather than resistance and avoidance.$q$),
  ('ins_v1_1', 'D7-03', 'LIKERT', 'D7', 3, '1-5', null, $q$Senior leaders visibly model the use of digital tools and data-driven approaches in their own daily ways of working and communicating.$q$),
  ('ins_v1_1', 'D7-04', 'LIKERT', 'D7', 4, '1-5', null, $q$Important business decisions are regularly and meaningfully informed by data analytics and digital insights, not solely by experience, intuition, or hierarchy.$q$),
  ('ins_v1_1', 'D7-05', 'LIKERT', 'D7', 5, '1-5', null, $q$Meaningful and ongoing investment is made in digital skills development at all organisational levels, not only for technically designated staff.$q$),
  ('ins_v1_1', 'D7-06', 'LIKERT', 'D7', 6, '1-5', null, $q$Employees feel genuinely confident suggesting technology-based improvements to existing processes and workflows without fear of their ideas being dismissed.$q$),
  ('ins_v1_1', 'D7-07', 'LIKERT', 'D7', 7, '1-5', null, $q$This organisation has a clear, communicated, and actionable digital strategy that employees at all levels understand and can connect to their daily responsibilities.$q$),
  ('ins_v1_1', 'D7-08', 'LIKERT', 'D7', 8, '1-5', null, $q$Digital transformation initiatives are actively sponsored and visibly championed at the executive level, not simply delegated to and managed within the IT function.$q$),
  ('ins_v1_1', 'D7-09', 'LIKERT', 'D7', 9, '1-5', null, $q$Before full organisational deployment, new digital approaches are regularly piloted at a smaller scale, creating structured space for learning, iteration, and improvement.$q$),
  ('ins_v1_1', 'D7-10', 'LIKERT', 'D7', 10, '1-5', null, $q$Failure in a digital experiment is consistently treated as a valuable learning opportunity and a sign of healthy risk-taking rather than a cause for blame or punitive accountability.$q$),
  ('ins_v1_1', 'D7-11', 'LIKERT', 'D7', 11, '1-5', null, $q$Cross-functional collaboration on digital projects happens naturally, proactively, and with minimal bureaucratic friction in this organisation.$q$),
  ('ins_v1_1', 'D7-12', 'LIKERT', 'D7', 12, '1-5', null, $q$Our workforce collectively possesses the digital literacy required to perform effectively in current roles and to adapt with reasonable ease to tomorrow's evolving digital requirements.$q$),
  ('ins_v1_1', 'D8-01', 'LIKERT', 'D8', 1, '1-5', null, $q$In this organisation, it is genuinely safe to take a reasonable professional or interpersonal risk, even when the outcome of that risk is genuinely uncertain.$q$),
  ('ins_v1_1', 'D8-02', 'LIKERT', 'D8', 2, '1-5', null, $q$People in this organisation can raise problems, surface concerns, and speak uncomfortable truths without realistic fear of negative consequences for their standing or career.$q$),
  ('ins_v1_1', 'D8-03', 'LIKERT', 'D8', 3, '1-5', null, $q$When mistakes occur in this organisation, they are approached as opportunities for collective learning and systemic improvement rather than as occasions for individual blame or shame.$q$),
  ('ins_v1_1', 'D8-04', 'LIKERT', 'D8', 4, '1-5', null, $q$Asking colleagues or managers for assistance (regardless of seniority or reporting-line relationships) is seen here as a sign of mature collaboration, not as personal weakness.$q$),
  ('ins_v1_1', 'D8-05', 'LIKERT', 'D8', 5, '1-5', null, $q$People here feel genuinely comfortable challenging decisions, plans, perspectives, or assumptions, including those expressed or endorsed by senior and executive leaders.$q$),
  ('ins_v1_1', 'D8-06', 'LIKERT', 'D8', 6, '1-5', null, $q$Diverse, dissenting, and unconventional viewpoints are actively sought out, carefully considered, and meaningfully incorporated when important organisational decisions are being made.$q$),
  ('ins_v1_1', 'D8-07', 'LIKERT', 'D8', 7, '1-5', null, $q$I can bring my authentic perspective and full identity to work in this organisation without needing to mask, suppress, or edit who I am or how I genuinely think.$q$),
  ('ins_v1_1', 'D8-08', 'LIKERT', 'D8', 8, '1-5', null, $q$Concerns about ethical issues, unfair treatment, unsafe practices, or value conflicts can be raised in this organisation without realistic fear of retaliation, marginalisation, or exclusion.$q$),
  ('ins_v1_1', 'D8-09', 'LIKERT', 'D8', 9, '1-5', null, $q$When a person sincerely disagrees with a decision that has been made, they are able to express that disagreement openly and directly without it damaging their professional standing or relationships.$q$),
  ('ins_v1_1', 'D8-10', 'LIKERT', 'D8', 10, '1-5', null, $q$This organisation's culture does not pressure people to perform certainty, project false confidence, or pretend they fully understand things they do not actually understand.$q$),
  ('ins_v1_1', 'D8-11', 'LIKERT', 'D8', 11, '1-5', null, $q$People in positions of authority in this organisation actively, visibly, and consistently invite challenge, productive dissent, and critical questioning rather than implicitly discouraging it.$q$),
  ('ins_v1_1', 'D8-12', 'LIKERT', 'D8', 12, '1-5', null, $q$Failures, setbacks, and near-miss incidents are discussed openly and constructively in this organisation so that collective learning occurs and avoidable mistakes are not repeated.$q$),
  ('ins_v1_1', 'D9-01', 'LIKERT', 'D9', 1, '1-5', null, $q$Leadership communicates clearly, consistently, and with genuine transparency about the purpose, rationale, and expected impacts of significant organisational changes.$q$),
  ('ins_v1_1', 'D9-02', 'LIKERT', 'D9', 2, '1-5', null, $q$Employees feel genuinely heard, acknowledged, and meaningfully considered when they raise concerns, questions, or reservations about planned changes and strategic directions.$q$),
  ('ins_v1_1', 'D9-03', 'LIKERT', 'D9', 3, '1-5', null, $q$There is a compelling, specific, and widely understood organisational vision for where this organisation is heading and the reasoning behind that direction.$q$),
  ('ins_v1_1', 'D9-04', 'LIKERT', 'D9', 4, '1-5', null, $q$Adequate and well-planned resources (including time, budget, and appropriately skilled people) are allocated to support major change and transformation initiatives.$q$),
  ('ins_v1_1', 'D9-05', 'LIKERT', 'D9', 5, '1-5', null, $q$Middle managers in this organisation actively champion, personally embody, and consistently role-model the changes that senior leadership is formally requesting.$q$),
  ('ins_v1_1', 'D9-06', 'LIKERT', 'D9', 6, '1-5', null, $q$When this organisation has undertaken significant transformation or change efforts in the past, it has generally followed through with sufficient discipline, sustained commitment, and visible results.$q$),
  ('ins_v1_1', 'D9-07', 'LIKERT', 'D9', 7, '1-5', null, $q$Effective feedback mechanisms exist that allow employees at all levels to share their honest views on how change is actually unfolding, and to have confidence those views are genuinely considered.$q$),
  ('ins_v1_1', 'D9-08', 'LIKERT', 'D9', 8, '1-5', null, $q$This organisation actively recognises, rewards, and publicly celebrates behaviours and outcomes that demonstrably align with its stated strategic direction and desired cultural values.$q$),
  ('ins_v1_1', 'D9-09', 'LIKERT', 'D9', 9, '1-5', null, $q$This organisation is able to sustain meaningful change momentum over a 12 to 24 month period without significant energy loss, widespread confusion, or visible reversion to previous patterns.$q$),
  ('ins_v1_1', 'D9-10', 'LIKERT', 'D9', 10, '1-5', null, $q$Employees at all levels understand concretely and specifically what new behaviours, priorities, and ways of working are expected of them during significant transformation efforts.$q$),
  ('ins_v1_1', 'D9-11', 'LIKERT', 'D9', 11, '1-5', null, $q$This organisation systematically and deliberately learns from past change efforts (both successes and instructive failures) and actively applies those lessons to subsequent transformation initiatives.$q$),
  ('ins_v1_1', 'D9-12', 'LIKERT', 'D9', 12, '1-5', null, $q$The pace, sequencing, and communication of change in this organisation feels coherent and manageable rather than chaotic, exhausting, poorly planned, or inadequately supported.$q$),
