  ('ins_v1_1', 'EOS-5', 'EOS', null, 5, '0-10', null, $q$How would you rate the transparency, openness, and quality of communication from organisational leadership?$q$),
  ('ins_v1_1', 'EOS-6', 'EOS', null, 6, '0-10', null, $q$How would you rate this organisation's tangible support for healthy work-life integration and genuine employee wellbeing?$q$),
